scwin.onpageload = function() {
    $w.log("main" + "_onpageload");
    if (console.log) {
        console.log("main" + "_onpageload");
    }
    localStorage.setItem("log5", "main" + "_onpageload");
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 개발자도구 콘솔을 열고 main샘플을 실행하고 콘솔을 확인한다.
    //1. Open the Developer Tools console, run the main sample, and check the console.
    //VErify 1. 아래와 같은 순서로 실행된다.main_externalJS sub_externalJS ww2_initscript ww1_initscript main_onpageload wq_uuid_3_contents_content2_body_onpageload wq_uuid_3_contents_content1_body_onpageload
    //1. It is executed in the following order. main_externalJS sub_externalJS ww2_initscript ww1_initscript main_onpageload wq_uuid_3_contents_content2_body_onpageload wq_uuid_3_contents_content1_body_onpageload
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log3')", "ww2_initscript");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log4')", "ww1_initscript");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log5')", "main_onpageload");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log6')", $p.id+"wq_uuid_3_contents_content1_body_onpageload");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log7')", $p.id+"wq_uuid_3_contents_content2_body_onpageload");
    WebSquare.wUnit.addCommand("pause", "500");
    //remove localStorage
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log3')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log4')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log5')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log6')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log7')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log8')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. tab3번을 클릭하고 콘솔을 확인한다.
    //2. Click tab3 and check the console.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3').setActiveTab(2)");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 아래의 순서가 추가되어 보여진다. ww3_initscript wq_uuid_3_contents_content3_body_onpageload
    //2. The following sequence is added. ww3_initscript wq_uuid_3_contents_content3_body_onpageload
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log8')", "ww3_initscript");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log9')", $p.id+"wq_uuid_3_contents_content3_body_onpageload");
    WebSquare.wUnit.addCommand("pause", "500");
    //remove localStorage
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log6')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log7')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log8')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log9')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 19-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
